using Microsoft.EntityFrameworkCore; using pet_project.Models;
namespace pet_project.Data;
public class AppDbContext:DbContext { public AppDbContext(DbContextOptions<AppDbContext> options):base(options){} public DbSet<Pet> Pets{get;set;}=null!; public DbSet<Shelter> Shelters{get;set;}=null!; public DbSet<Adopter> Adopters{get;set;}=null!; public DbSet<AdoptionApplication> AdoptionApplications{get;set;}=null!; protected override void OnModelCreating(ModelBuilder b){b.Entity<Pet>().HasOne(p=>p.Shelter).WithMany(s=>s.Pets).HasForeignKey(p=>p.ShelterId).OnDelete(DeleteBehavior.Cascade);b.Entity<AdoptionApplication>().HasOne(a=>a.Pet).WithMany(p=>p.Applications).HasForeignKey(a=>a.PetId).OnDelete(DeleteBehavior.Cascade);b.Entity<AdoptionApplication>().HasOne(a=>a.Adopter).WithMany(x=>x.Applications).HasForeignKey(a=>a.AdopterId).OnDelete(DeleteBehavior.Cascade);}}
